class Solution {
public:
 long long maximizeXorAndXor(vector<int>& nums){int n=nums.size();long long best=0;
  for(int mask=0;mask<(1<<n);++mask){int aand=-1,x=0;vector<int>v;for(int i=0;i<n;++i)if(mask>>i&1)aand&=nums[i];else{x^=nums[i];v.push_back(nums[i]);}
   if(aand<0)aand=0;int basis[31]={};int freeBits=~x;
   for(int z:v){z&=freeBits;for(int b=30;b>=0;--b)if(z>>b&1){if(!basis[b]){basis[b]=z;break;}z^=basis[b];}}
   int y=0;for(int b=30;b>=0;--b)y=max(y,y^basis[b]);
   best=max(best,(long long)aand+x+2LL*y);
  }return best;
 }
};
